			dir := t.TempDir()
			path, jsonPath := filepath.Join(dir, tc.name+".jsonl"), filepath.Join(dir, "summary.json")
			if err := os.WriteFile(path, []byte(tc.transcript), 0600); err != nil {
				t.Fatal(err)
			}
			output, err := os.Create(filepath.Join(dir, "stdout"))
			if err != nil {
				t.Fatal(err)
			}
			old := os.Stdout
			os.Stdout = output
			err = run([]string{"--transcripts", path, "--json", jsonPath})
			os.Stdout = old
			output.Close()
			if exitCode(err) != 0 {
				t.Fatal(err)
			}
			if got, _ := os.ReadFile(output.Name()); string(got) != nativeText(tc.report+"\nwrote "+jsonPath+"\n") {
				t.Fatalf("report: got %q, want %q", got, tc.report)
			}
